    private static bool ValidPolicy(JsonElement policy)
    {
        static bool Text(JsonElement value,string key,int min,int max,bool trim=false)=>value.TryGetProperty(key,out var property)&&property.ValueKind==JsonValueKind.String&&(trim?property.GetString()!.Trim():property.GetString()!).Length>=min&&(trim?property.GetString()!.Trim():property.GetString()!).Length<=max;
        static bool Keys(JsonElement value,string[] required,string? optional=null)=>value.ValueKind==JsonValueKind.Object&&required.All(key=>value.TryGetProperty(key,out _))&&value.EnumerateObject().All(p=>required.Contains(p.Name)||p.Name==optional);
        if(!Keys(policy,["id","purpose","provider","processing_location","storage_location","retention","external_processing"],"processors")||
            !Text(policy,"id",1,64)||!System.Text.RegularExpressions.Regex.IsMatch(policy.GetProperty("id").GetString()!,@"\A[a-z0-9-]{1,64}\z")||
            !Text(policy,"purpose",1,30)||policy.GetProperty("purpose").GetString()!="work_records"||!Text(policy,"provider",1,80)||
            !Text(policy,"processing_location",1,100)||!Text(policy,"storage_location",1,100)||!Text(policy,"retention",1,40)||policy.GetProperty("retention").GetString()!="until_user_deletes"||
            policy.GetProperty("external_processing").ValueKind is not (JsonValueKind.True or JsonValueKind.False))return false;
        if(!policy.TryGetProperty("processors",out var processors))return true;
        if(!policy.GetProperty("external_processing").GetBoolean()||processors.ValueKind!=JsonValueKind.Array||processors.GetArrayLength()!=1)return false;
        var processor=processors[0];
        return Keys(processor,["purpose","provider","processing_location","storage_location","retention"])&&Text(processor,"purpose",1,30)&&processor.GetProperty("purpose").GetString()=="long_stt"&&
            Text(processor,"provider",1,80)&&processor.GetProperty("provider").GetString() is "openai" or "clova_speech"&&
            Text(processor,"processing_location",1,200,true)&&Text(processor,"storage_location",1,200,true)&&Text(processor,"retention",1,200,true);
    }

